// W7 B3：我方暫停鈕——⚙ 換人鈕同排（左側）；死球窗＋有額度才可按，其餘反灰（同 subPanel 鈕範式）；
// 點擊呼叫 handlers.requestTimeout（matchLoop 開機注入＝唯一執行路徑，走 sim applyTimeout）
function createTimeoutButton({ handlers, playerId }) {
  const btn = document.createElement('button');
  // 大作感卷 批4：黑底金框斜切 chip（凍結檔範圍 item 3 明文點名「暫停」）
  btn.className = 'vd-chip-gold vd-skew';
  btn.style.cssText = [
    // 試玩回饋 07-24（#1）：改直排——⏱ 放 ⚙ 換人鈕正下方（同欄第四格）
    'position:fixed', 'top:calc(env(safe-area-inset-top, 0px) + 164px)',
    'right:calc(env(safe-area-inset-right, 0px) + 12px)',
    'height:44px', 'padding:0 14px', 'font-size:14px',
    'z-index:16', 'cursor:pointer', 'touch-action:manipulation',
  ].join(';');
  btn.textContent = '⏱ 暫停';
  btn.addEventListener('pointerdown', (e) => {
    e.stopPropagation();
    if (btn.dataset.enabled !== '1') return;
    handlers.requestTimeout?.();
  });
  document.body.appendChild(btn);
  return {
    el: btn,
    // 每幀同步：死球窗＋還有額度＋本分未喊過（W4 07-27：同一分每隊至多一次）才可按
    sync(g) {
      const team = g.players[playerId].teamId;
      const remaining = g.timeouts?.[team]?.remaining ?? 0;
      const usable = g.phase === 'serve' && remaining > 0 && !timeoutUsedThisPoint(g, team);
      btn.dataset.enabled = usable ? '1' : '0';
      btn.style.opacity = usable ? '1' : '0.45';
      btn.textContent = `⏱ 暫停×${remaining}`;
      if (g.phase === 'set_over') btn.style.display = 'none';
    },
  };
}

